package com.labex.labexagent.run;import static org.mockito.Mockito.*;import com.labex.entity.AgentSubagent;import com.labex.entity.StudentProject;import java.nio.file.Path;import java.util.concurrent.CompletableFuture;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class SubagentDispatchServiceTest {@TempDir Path root;@Test void persistsThenSchedulesTheSubagent(){AgentSubagentService subs=mock(AgentSubagentService.class);SubagentScheduler scheduler=mock(SubagentScheduler.class);LlmSubagentExecutor executor=mock(LlmSubagentExecutor.class);AgentSubagent a=new AgentSubagent();a.setSubagentId(1L);when(subs.create(any(),any(),any(),any(),anyInt(),any(),any(),anyBoolean())).thenReturn(a);when(scheduler.schedule(any(),any(),any(),any(),any(),any(),any())).thenReturn(CompletableFuture.completedFuture(null));StudentProject p=new StudentProject();p.setWorkspacePath(root.toString());var dispatch=new SubagentDispatchService(subs,scheduler,executor).dispatch("s",7,p,"c",9L,"review","check code",null,100,"[]","[]",false);verify(scheduler).schedule(eq("s"),eq(7),eq(p),eq("c"),eq(9L),eq(a),eq(executor));dispatch.completion().join();}}
